(function(root){'use strict';
const choices=['A更好','B更好','两者接近','问题不同，难以排序','不确定','参考或范围有问题'];
function bounds(group){const all=[group.reference,...group.cases].flatMap(g=>[...g.bottom,...g.top]);const min=[0,1,2].map(i=>Math.min(...all.map(p=>p[i]))),max=[0,1,2].map(i=>Math.max(...all.map(p=>p[i])));const center=min.map((x,i)=>(x+max[i])/2);const radius=Math.max(...all.map(p=>Math.hypot(...p.map((x,i)=>x-center[i]))));return{center,radius};}
function project(p,b,cam,w,h){const [x,y,z]=p.map((x,i)=>x-b.center[i]);const yaw=cam.yaw*Math.PI/180,pitch=cam.pitch*Math.PI/180;const u=x*Math.cos(yaw)-z*Math.sin(yaw),d=x*Math.sin(yaw)+z*Math.cos(yaw),v=y*Math.cos(pitch)-d*Math.sin(pitch);const scale=Math.min(w,h)*.40/b.radius*cam.zoom;return{x:w/2+u*scale,y:h/2-v*scale,depth:y*Math.sin(pitch)+d*Math.cos(pitch),scale};}
function fresh(d){return{schema_version:'quality_geometry_supplement_v1',dataset_id:d.dataset_id,parent_dataset_id:d.parent_dataset_id,review_type:'numeric_assisted_development_rereview',created_at:new Date().toISOString(),answers:Object.fromEntries(d.groups.map(g=>[g.id,{choice:null,comment:'',updated_at:null,first_viewed_at:null}]))};}
function validate(v,d){if(!v||v.dataset_id!==d.dataset_id||v.schema_version!=='quality_geometry_supplement_v1')throw Error('补充回执的数据集或版本不匹配。');const o=fresh(d);if(!v.answers||typeof v.answers!=='object')throw Error('回执缺少answers。');for(const k of Object.keys(v.answers))if(!o.answers[k])throw Error('未知题号。');for(const g of d.groups){const a=v.answers[g.id];if(!a)continue;if(a.choice!=null&&!choices.includes(a.choice))throw Error('无效选择。');if(a.comment!=null&&(typeof a.comment!=='string'||a.comment.length>10000))throw Error('评论格式无效。');o.answers[g.id]={choice:a.choice??null,comment:a.comment??'',updated_at:typeof a.updated_at==='string'?a.updated_at:null,first_viewed_at:typeof a.first_viewed_at==='string'?a.first_viewed_at:null};}o.created_at=typeof v.created_at==='string'?v.created_at:o.created_at;return o;}
function receipt(s){return{...s,exported_at:new Date().toISOString(),unanswered_is_negative:false,answers:Object.fromEntries(Object.entries(s.answers).map(([k,v])=>[k,{...v,status:v.choice==null?'not_reviewed':'answered'}]))};}
const api={choices,bounds,project,fresh,validate,receipt};root.GeometryCore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
